package org.usbworkbench;
import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.zip.CRC32;
public final class BenchToolsTest {
 static int checks;interface Action{void run()throws Exception;}static void yes(boolean b,String why){if(!b)throw new AssertionError(why);checks++;}static void fail(String prefix,Action a)throws Exception{try{a.run();throw new AssertionError(prefix);}catch(IOException e){yes(e.getMessage().startsWith(prefix),e.toString());}}
 static class Disk extends DiskToolsTest.MemoryDisk{boolean recording,fault;List<Long> order=new ArrayList<>();Disk(){super(131072,512);}public void write(long at,byte[] b,int n)throws IOException{if(recording){order.add(at);if(fault)throw new IOException("OWNED_IO");}super.write(at,b,n);}}
 static Disk gpt()throws Exception{Disk d=new Disk();AdvancedDiskTools.installGpt(d,2048,d.count-34,"OLD");byte[] b=new byte[65536];new Random(4).nextBytes(b);d.write(2048,b,b.length);return d;}
 static byte[] table(Disk d,long start)throws Exception{byte[] b=new byte[16384];d.read(start,b,b.length);return b;}
 static long crc(byte[] b){CRC32 c=new CRC32();c.update(b);return c.getValue();}
 static void fix(Disk d,byte[] table)throws Exception{for(long at:new long[]{2,d.count-33})d.write(at,table,table.length);for(long at:new long[]{1,d.count-1}){byte[] h=d.at(at);DiskTools.le32(h,88,crc(table));DiskTools.le32(h,16,0);DiskTools.le32(h,16,crc(Arrays.copyOf(h,92)));d.write(at,h,512);}}
 static Disk mbr()throws Exception{Disk d=new Disk();byte[] b=new byte[512];new Random(2).nextBytes(b);Arrays.fill(b,446,510,(byte)0);b[450]=7;DiskTools.le32(b,454,2048);DiskTools.le32(b,458,10000);b[466]=(byte)0x83;DiskTools.le32(b,470,20000);DiskTools.le32(b,474,10000);b[446]=(byte)128;b[510]=85;b[511]=(byte)170;d.write(0,b,512);return d;}
 static byte[] adc(byte[] packed)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();try(AdcInputStream in=new AdcInputStream(new ByteArrayInputStream(packed))){byte[] b=new byte[7];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}return out.toByteArray();}
 static byte[] literal(byte[] data)throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();for(int at=0;at<data.length;at+=128){int n=Math.min(128,data.length-at);out.write(128+n-1);out.write(data,at,n);}return out.toByteArray();}
 public static byte[] ownedDmg(byte[] packed,byte[] expected,long type)throws Exception{byte[] block=new byte[284];ByteBuffer b=ByteBuffer.wrap(block).order(ByteOrder.BIG_ENDIAN);b.put("mish".getBytes(StandardCharsets.US_ASCII)).putInt(1).putLong(0).putLong(expected.length/512).putLong(0);b.putInt(64,2);b.putInt(68,32);b.putInt(72,(int)crc(expected));b.putInt(200,2);b.position(204);b.putInt((int)type).putInt(0).putLong(0).putLong(expected.length/512).putLong(0).putLong(packed.length);b.putInt(-1).putInt(0).putLong(expected.length/512).putLong(0).putLong(0).putLong(0);byte[] xml=("<plist><dict><key>Data</key><data>"+Base64.getEncoder().encodeToString(block)+"</data></dict></plist>").getBytes(StandardCharsets.UTF_8);byte[] footer=new byte[512];b=ByteBuffer.wrap(footer).order(ByteOrder.BIG_ENDIAN);b.put("koly".getBytes(StandardCharsets.US_ASCII)).putInt(4).putInt(512);b.putLong(24,0);b.putLong(32,packed.length);b.putInt(56,1);b.putInt(60,1);b.putLong(216,packed.length);b.putLong(224,xml.length);b.putLong(492,expected.length/512);ByteArrayOutputStream out=new ByteArrayOutputStream();out.write(packed);out.write(xml);out.write(footer);return out.toByteArray();}
 static OpticalImage.Source source(byte[] b){return new OpticalImage.Source(){public long size(){return b.length;}public void read(long at,byte[] dst,int off,int n)throws IOException{if(at<0||n>b.length-at)throw new IOException("BOUNDS");System.arraycopy(b,(int)at,dst,off,n);}public void close(){}};}
 public static void main(String[] args)throws Exception{
  Disk d=gpt();byte[] original=table(d,2),payload=table(d,2048),m=d.at(0);int writes=d.writes;PartitionMetadata.Plan p=PartitionMetadata.plan(d,"gptName",1,"بيانات USB");yes(d.writes==writes,"planning is read only");d.recording=true;String result=PartitionMetadata.apply(d,p,(a,b)->{});yes(result.startsWith("PARTITION_EDIT_OK"),"edit verified");yes(d.order.equals(Arrays.asList(d.count-33,d.count-1,2L,1L)),"backup table/header first, primary table/header last");yes(AdvancedDiskTools.inspectGpt(d).contains("CRC OK"),"both CRC copies valid");yes(Arrays.equals(payload,table(d,2048))&&Arrays.equals(m,d.at(0)),"volume data and MBR untouched");byte[] changed=table(d,2),expected=original.clone();Arrays.fill(expected,56,128,(byte)0);byte[] name="بيانات USB".getBytes(StandardCharsets.UTF_16LE);System.arraycopy(name,0,expected,56,name.length);yes(Arrays.equals(expected,changed),"only selected GPT name bytes changed");yes(Arrays.equals(changed,table(d,d.count-33)),"backup mirrored");yes(ReportText.render(result,true).contains("اسم قسم GPT")&&!ReportText.render(result,true).contains("written"),"Arabic success report");yes(ReportText.render(result,false).contains("بيانات USB"),"raw Unicode name retained");writes=d.writes;result=PartitionMetadata.apply(d,PartitionMetadata.plan(d,"gptName",1,"بيانات USB"),(a,b)->{});yes(result.equals("PARTITION_EDIT_UNCHANGED")&&d.writes==writes,"matching name makes zero writes");
  Disk stale=gpt();PartitionMetadata.Plan stalePlan=PartitionMetadata.plan(stale,"gptName",1,"NEW");byte[] mutate=stale.at(0);mutate[10]^=1;stale.write(0,mutate,512);writes=stale.writes;fail("PARTITION_CHANGED",()->PartitionMetadata.apply(stale,stalePlan,(a,b)->{}));yes(stale.writes==writes,"changed plan no writes");
  Disk cancel=gpt();PartitionMetadata.Plan cp=PartitionMetadata.plan(cancel,"gptName",1,"NEW");writes=cancel.writes;fail("CANCELLED",()->PartitionMetadata.apply(cancel,cp,(a,b)->{throw new IOException("CANCELLED");}));yes(cancel.writes==writes,"cancel before first write");
  Disk fault=gpt();PartitionMetadata.Plan fp=PartitionMetadata.plan(fault,"gptName",1,"NEW");fault.recording=true;fault.fault=true;fail("PARTITION_EDIT_INCOMPLETE",()->PartitionMetadata.apply(fault,fp,(a,b)->{}));yes(fault.order.size()==1,"failed writes not retried");yes(AdvancedDiskTools.inspectGpt(fault).contains("CRC OK"),"prewrite injected fault leaves original GPT");
  Disk partial=gpt();PartitionMetadata.Plan pp=PartitionMetadata.plan(partial,"gptName",1,"NEW");byte[] partialPrimary=table(partial,2);partial.recording=true;fail("PARTITION_EDIT_INCOMPLETE",()->PartitionMetadata.apply(partial,pp,(a,b)->{if(a==1)throw new IOException("CANCELLED");}));yes(partial.order.equals(Collections.singletonList(partial.count-33)),"post-write cancellation stops immediately");yes(Arrays.equals(partialPrimary,table(partial,2)),"primary remains original after partial backup write");
  for(String bad:new String[]{""," x","x ","a\nb","😀","a\u202eb","123456789012345678901234567890123456"})fail("PARTITION_NAME",()->PartitionMetadata.name(bad));PartitionMetadata.name("عربي-123");yes(true,"Arabic name valid");
  Disk wrong=gpt();writes=wrong.writes;fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(wrong,"gptName",2,"NEW"));fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(wrong,"mbrActive",1,""));yes(wrong.writes==writes,"empty GPT entry/protective MBR rejected without writes");
  byte[] entries=table(wrong,2);System.arraycopy(entries,0,entries,128,128);entries[128+16]^=1;fix(wrong,entries);fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(wrong,"gptName",1,"NEW"));yes(true,"overlapping GPT rejected");
  Disk active=mbr();byte[] before=active.at(0);p=PartitionMetadata.plan(active,"mbrActive",2,"");PartitionMetadata.apply(active,p,(a,b)->{});byte[] after=active.at(0),onlyFlags=before.clone();onlyFlags[446]=0;onlyFlags[462]=(byte)128;yes(Arrays.equals(after,onlyFlags),"MBR only active flag bytes changed");writes=active.writes;fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(active,"mbrActive",3,""));yes(active.writes==writes,"empty MBR selection rejected");after[466]=15;active.write(0,after,512);fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(active,"mbrActive",1,""));
  fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(active,null,1,""));
  DiskToolsTest.MemoryDisk fourK=new DiskToolsTest.MemoryDisk(10000,4096);fail("PARTITION_LAYOUT",()->PartitionMetadata.plan(fourK,"gptName",1,"NEW"));
  yes(Arrays.equals(adc(new byte[]{(byte)0x82,65,66,67,0,2,0x40,0,5}),"ABCABCABCA".getBytes(StandardCharsets.US_ASCII)),"independent literal/short/long vector");yes(Arrays.equals(adc(new byte[]{(byte)128,65,0x3c,0}),"AAAAAAAAAAAAAAAAAAA".getBytes(StandardCharsets.US_ASCII)),"overlapping distance1 short-copy max18");
  for(int length:new int[]{0,1,127,128,129,65535,65536,65537,131073}){byte[] plain=new byte[length];new Random(length).nextBytes(plain);yes(Arrays.equals(adc(literal(plain)),plain),"stream literals/window "+length);}
  ByteArrayOutputStream packed=new ByteArrayOutputStream();byte[] prefix=new byte[65536];new Random(5).nextBytes(prefix);packed.write(literal(prefix));packed.write(new byte[]{0x7f,(byte)255,(byte)255});byte[] longExpected=Arrays.copyOf(prefix,prefix.length+67);System.arraycopy(prefix,0,longExpected,65536,67);yes(Arrays.equals(adc(packed.toByteArray()),longExpected),"distance65536 and long-copy67 window wrap");
  for(byte[] bad:new byte[][]{{0,0},{0x40,0},{(byte)0xff,1},{(byte)128},{(byte)128,1,0},{(byte)128,1,0,1}})fail("DMG_DATA",()->adc(bad));
  byte[] plain=new byte[1024];new Random(7).nextBytes(plain);byte[] image=ownedDmg(literal(plain),plain,0x80000004L);ByteArrayOutputStream out=new ByteArrayOutputStream();yes(DmgConverter.budget(source(image),1024,(a,b)->{})==1024,"ADC DMG preflight");ImageContainers.Result converted=DmgConverter.convert(source(image),out,1024,(a,b)->{});yes(Arrays.equals(out.toByteArray(),plain),"ADC DMG every byte matches independently generated payload");ImageContainers.verify("dmgRaw",source(out.toByteArray()),converted,(a,b)->{});yes(true,"ADC output SHA256 readback");
  fail("DMG_DATA",()->DmgConverter.budget(source(ownedDmg(new byte[]{(byte)128,1},plain,0x80000004L)),1024,(a,b)->{}));fail("DMG_UNSUPPORTED",()->DmgConverter.budget(source(ownedDmg(literal(plain),plain,0x80000006L)),1024,(a,b)->{}));byte[] extra=Arrays.copyOf(literal(plain),literal(plain).length+2);extra[extra.length-2]=(byte)128;fail("DMG_DATA",()->DmgConverter.budget(source(ownedDmg(extra,plain,0x80000004L)),1024,(a,b)->{}));fail("CANCELLED",()->DmgConverter.budget(source(image),1024,(a,b)->{throw new IOException("CANCELLED");}));
  System.out.println("PASS: "+checks+" partition metadata/name/MBR/CRC/preservation/failure/cancel/no-op and streaming ADC/UDIF/bounds/CRC/readback checks");
 }
}
